$(function(){lazyLoadOptions={scrollDirection:"vertical",effect:"fadeIn",effectTime:300,placeholder:"",onError:function(o){console.log("[lazyload] Error loading "+o.data("src"))},afterLoad:function(o){o.is("img")?(o.css("background-image","none"),o.css("min-height","0")):o.is("div")&&(o.css("background-size","cover"),o.css("background-position","center"))}},$("img.lazy, div.lazy:not(.always-load)").Lazy({visibleOnly:!0,...lazyLoadOptions}),$("div.lazy.always-load").Lazy({visibleOnly:!1,...lazyLoadOptions}),$('[data-toggle="tooltip"]').tooltip()});